#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Simple dynamic array of strings for results
typedef struct {
    char **data;
    int size;
    int cap;
} StrVec;

static void sv_init(StrVec *v) { v->data = NULL; v->size = 0; v->cap = 0; }
static void sv_push(StrVec *v, const char *s) {
    if (v->size == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 8;
        v->data = realloc(v->data, v->cap * sizeof(char*));
    }
    v->data[v->size++] = strdup(s);
}
static void sv_free(StrVec *v) { for (int i = 0; i < v->size; ++i) free(v->data[i]); free(v->data); }

void backtrack(const char **map, const char *digits, int idx, char *buf, StrVec *out) {
    if (digits[idx] == '\0') {
        sv_push(out, buf);
        return;
    }
    const char *letters = map[digits[idx] - '0'];
    for (int i = 0; letters[i]; ++i) {
        buf[idx] = letters[i];
        buf[idx+1] = '\0';
        backtrack(map, digits, idx+1, buf, out);
    }
}

char** letterCombinations(char* digits, int* returnSize) {
    *returnSize = 0;
    if (!digits || digits[0] == '\0') return NULL;
    const char *map[10] = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    StrVec out; sv_init(&out);
    int n = strlen(digits);
    char *buf = malloc(n + 1);
    buf[0] = '\0';
    backtrack(map, digits, 0, buf, &out);
    free(buf);
    *returnSize = out.size;
    return out.data; // caller must free each string and the array
}

int main() {
    char line[1024];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    int len = strlen(line); while (len > 0 && (line[len-1]=='\n' || line[len-1]=='\r')) line[--len] = '\0';
    // parse ["digits"]
    char *first = strchr(line, '"');
    if (!first) { printf("[]\n"); return 0; }
    char *last = strrchr(line, '"');
    if (!last || last == first) { printf("[]\n"); return 0; }
    int n = (int)(last - first - 1);
    char *digits = malloc(n + 1);
    strncpy(digits, first + 1, n);
    digits[n] = '\0';

    int returnSize = 0;
    char **res = letterCombinations(digits, &returnSize);
    printf("[");
    for (int i = 0; i < returnSize; ++i) {
        printf("\"%s\"", res[i]);
        if (i + 1 < returnSize) printf(",");
        free(res[i]);
    }
    printf("]\n");
    free(res);
    free(digits);
    return 0;
}

