#include <bits/stdc++.h>
using namespace std;

vector<string> letterCombinations(string digits) {
    if (digits.empty()) return {};
    vector<string> mapping(10);
    mapping[2] = "abc"; mapping[3] = "def"; mapping[4] = "ghi"; mapping[5] = "jkl";
    mapping[6] = "mno"; mapping[7] = "pqrs"; mapping[8] = "tuv"; mapping[9] = "wxyz";
    vector<string> res;
    string cur(digits.size(), '\0');
    function<void(int)> dfs = [&](int idx) {
        if (idx == (int)digits.size()) { res.push_back(cur); return; }
        string &letters = mapping[digits[idx] - '0'];
        for (char c : letters) {
            cur[idx] = c;
            dfs(idx + 1);
        }
    };
    dfs(0);
    return res;
}

int main() {
    string line; if (!getline(cin, line)) return 0;
    auto first = line.find('"'); if (first == string::npos) { cout << "[]\n"; return 0; }
    auto last = line.rfind('"'); string digits = line.substr(first+1, last-first-1);
    auto res = letterCombinations(digits);
    cout << "[";
    for (size_t i = 0; i < res.size(); ++i) {
        cout << '"' << res[i] << '"';
        if (i + 1 < res.size()) cout << ",";
    }
    cout << "]\n";
    return 0;
}

