import java.io.*;
import java.util.*;

class Solution {
    private static final Map<Character, String> MAPPING = new HashMap<>();
    static {
        MAPPING.put('2', "abc"); MAPPING.put('3', "def"); MAPPING.put('4', "ghi");
        MAPPING.put('5', "jkl"); MAPPING.put('6', "mno"); MAPPING.put('7', "pqrs");
        MAPPING.put('8', "tuv"); MAPPING.put('9', "wxyz");
    }

    public List<String> letterCombinations(String digits) {
        List<String> res = new ArrayList<>();
        if (digits == null || digits.length() == 0) return res;
        backtrack(digits, 0, new StringBuilder(), res);
        return res;
    }

    private void backtrack(String digits, int idx, StringBuilder sb, List<String> res) {
        if (idx == digits.length()) {
            res.add(sb.toString());
            return;
        }
        String letters = MAPPING.get(digits.charAt(idx));
        for (char c : letters.toCharArray()) {
            sb.append(c);
            backtrack(digits, idx + 1, sb, res);
            sb.deleteCharAt(sb.length() - 1);
        }
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        String digits = line.substring(1, line.length() - 1).replaceAll("\"", "");
        List<String> res = new Solution().letterCombinations(digits);
        System.out.println(res.toString().replace(" ", ""));
    }
}

